fn greet_with_punctuation(name: Str, punct: Str) -> Str {
  return "Hello, " + name + punct;
}

fn greet_default(name: Str) -> Str {
  return greet_with_punctuation(name, "!");
}

fn main() -> Int {
  let msg = greet_default("XIOM");
  io.println(msg);
  return 0;
}
